enum class chars_format {

    scientific = /*unspecified*/,

    fixed = /*unspecified*/,

    hex = /*unspecified*/,

    general = fixed | scientific

};

examples.code:
#include <charconv>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    char buffer[32];
    auto result = std::to_chars(buffer, buffer + 32, 1.5, std::chars_format::fixed, 1);
    assert(result.ec == std::errc{});
    double value{};
    auto parsed = std::from_chars(buffer, result.ptr, value, std::chars_format::fixed);
    assert(parsed.ec == std::errc{} && value == 1.5);
}
